package com.citacloud.springboot.contacloud.app.views.components;
import com.citacloud.springboot.contacloud.app.dto.*; import com.citacloud.springboot.contacloud.app.errors.UiErrorHandler; import com.citacloud.springboot.contacloud.app.models.*; import com.citacloud.springboot.contacloud.app.services.RecuentoCajaService;
import com.vaadin.flow.component.*; import com.vaadin.flow.component.button.Button; import com.vaadin.flow.component.confirmdialog.ConfirmDialog; import com.vaadin.flow.component.dialog.Dialog; import com.vaadin.flow.component.grid.*; import com.vaadin.flow.component.html.*; import com.vaadin.flow.component.icon.VaadinIcon; import com.vaadin.flow.component.orderedlayout.*; import com.vaadin.flow.component.textfield.*; import org.springframework.data.domain.Page;
import java.math.BigDecimal; import java.time.format.DateTimeFormatter; import java.util.*; import java.util.function.Consumer;
public final class RecuentoCajaDialog extends Dialog {
 private static final DateTimeFormatter DT=DateTimeFormatter.ofPattern("dd/MM/yyyy HH:mm"); private final RecuentoCajaService service; private final UUID sesionId; private final Consumer<UUID> imprimir; private final Map<UUID,IntegerField> campos=new LinkedHashMap<>(); private final Span total=new Span(); private PreparacionRecuentoCajaDto preparacion; private UUID clave=UUID.randomUUID(); private TextArea observacion; private AppActionButton guardar;
 public RecuentoCajaDialog(UUID sesion,RecuentoCajaService service,Consumer<UUID> imprimir){this.sesionId=sesion;this.service=service;this.imprimir=imprimir;setHeaderTitle("RECUENTO DE CAJA");setWidth("min(760px,96vw)");setMaxHeight("92vh");addClassName("cc-cash-count-dialog");addOpenedChangeListener(e->{if(e.isOpened())cargar();});}
 private void cargar(){try{preparacion=service.preparar(sesionId);formulario();}catch(RuntimeException ex){UiErrorHandler.show(ex,"No fue posible preparar el recuento de caja.");close();}}
 private void formulario(){removeAll();getFooter().removeAll();campos.clear();Div cab=new Div(new H3(preparacion.caja()+" · "+preparacion.sucursal()),new Span("● Abierta"));cab.addClassName("cc-cash-count-heading");HorizontalLayout info=new HorizontalLayout(info("Fecha/Hora",DT.format(preparacion.fechaHora())),info("Usuario",preparacion.usuario()),info("Moneda",preparacion.monedaCodigo()));info.setWidthFull();info.setFlexGrow(1,info.getChildren().toArray(Component[]::new));VerticalLayout cuerpo=new VerticalLayout();cuerpo.setPadding(false);cuerpo.setSpacing(false);cuerpo.add(new H4("CONTEO FÍSICO"));TipoDenominacionCaja anterior=null;for(var d:preparacion.denominaciones()){if(d.tipo()!=anterior){Span grupo=new Span(d.tipo()==TipoDenominacionCaja.BANKNOTE?"BILLETES":"MONEDAS");grupo.addClassName("cc-cash-count-group");cuerpo.add(grupo);anterior=d.tipo();}IntegerField cantidad=new IntegerField();cantidad.setMin(0);cantidad.setMax(1_000_000);cantidad.setStepButtonsVisible(false);cantidad.setPlaceholder("0");cantidad.setWidth("120px");Span subtotal=new Span("0.00");subtotal.addClassName("cc-cash-count-money");cantidad.addValueChangeListener(e->{int q=e.getValue()==null?0:e.getValue();subtotal.setText(money(d.valor().multiply(BigDecimal.valueOf(q))));actualizarTotal();});campos.put(d.id(),cantidad);HorizontalLayout fila=new HorizontalLayout(new Span(preparacion.monedaSimbolo()+" "+money(d.valor())),cantidad,subtotal);fila.addClassName("cc-cash-count-row");fila.setWidthFull();fila.setFlexGrow(1,fila.getComponentAt(0));cuerpo.add(fila);}total.setText(preparacion.monedaCodigo()+" 0.00");Div totalBox=new Div(new Span("TOTAL CONTADO"),total);totalBox.addClassName("cc-cash-count-total");observacion=new TextArea("Observación");observacion.setMaxLength(500);observacion.setWidthFull();Button historial=new Button("Historial de recuentos",VaadinIcon.CLOCK.create(),e->historial());historial.addClassName("cc-pos-secondary");add(cab,info,cuerpo,totalBox,observacion,historial);guardar=new AppActionButton(ActionType.SAVE,ButtonSize.MAIN,"Guardar recuento",e->guardar());AppActionButton cerrar=new AppActionButton(ActionType.CLOSE,ButtonSize.MAIN,"Cerrar",e->cerrarSeguro());getFooter().add(guardar,cerrar);}
 private void actualizarTotal(){BigDecimal t=BigDecimal.ZERO;for(var d:preparacion.denominaciones()){Integer q=campos.get(d.id()).getValue();if(q!=null)t=t.add(d.valor().multiply(BigDecimal.valueOf(q)));}total.setText(preparacion.monedaCodigo()+" "+money(t));}
 private void guardar(){guardar.setEnabled(false);try{List<GuardarRecuentoCajaInput.Cantidad> cantidades=campos.entrySet().stream().map(e->new GuardarRecuentoCajaInput.Cantidad(e.getKey(),Optional.ofNullable(e.getValue().getValue()).orElse(0))).toList();RecuentoCajaDto r=service.guardar(new GuardarRecuentoCajaInput(sesionId,clave,cantidades,observacion.getValue()));resultado(r);}catch(RuntimeException ex){guardar.setEnabled(true);UiErrorHandler.show(ex,"No fue posible guardar el recuento de caja.");}}
 private void resultado(RecuentoCajaDto r){removeAll();getFooter().removeAll();setHeaderTitle("RESULTADO DEL RECUENTO");Div generales=new Div(info("Número",r.numero()),info("Caja",r.caja()+" · "+r.sucursal()),infoTruncado("Apertura",r.apertura()),info("Fecha/Hora",DT.format(r.contadoEn())),info("Usuario",r.usuario()),info("Moneda",r.monedaCodigo()));generales.addClassName("cc-cash-count-result-grid");Div estado=new Div(new H3(label(r.resultado())));estado.addClassNames("cc-cash-count-result","cc-result-"+r.resultado().name().toLowerCase());Div resumen=new Div(new H4("RESULTADO"),filaResultado("Total esperado",amount(r,r.esperado())),filaResultado("Total contado",amount(r,r.contado())),filaResultado("Diferencia",signed(r,r.diferencia())),estado);resumen.addClassName("cc-cash-count-result-summary");VerticalLayout contenido=new VerticalLayout(generales,resumen);contenido.setPadding(false);contenido.setSpacing(false);if(!r.detalles().isEmpty()){Grid<RecuentoCajaDto.Detalle> detail=new Grid<>();detail.addColumn(x->r.monedaSimbolo()+" "+money(x.denominacion())).setHeader("Denominación");detail.addColumn(RecuentoCajaDto.Detalle::cantidad).setHeader("Cantidad").setTextAlign(ColumnTextAlign.END);detail.addColumn(x->money(x.subtotal())).setHeader("Subtotal").setTextAlign(ColumnTextAlign.END);detail.setItems(r.detalles());detail.setAllRowsVisible(true);contenido.add(new H4("CONTEO FÍSICO"),detail);}if(r.observacion()!=null&&!r.observacion().isBlank())contenido.add(info("Observación",r.observacion()));add(contenido);AppActionButton print=new AppActionButton(ActionType.PRINT,ButtonSize.MAIN,"Imprimir recuento",e->imprimir.accept(r.id()));AppActionButton close=new AppActionButton(ActionType.CLOSE,ButtonSize.MAIN,"Cerrar",e->close());getFooter().add(print,close);}
 private void historial(){Dialog d=new Dialog();d.setHeaderTitle("HISTORIAL DE RECUENTOS");d.setWidth("min(980px,96vw)");Grid<RecuentoCajaDto> g=new Grid<>();g.addColumn(x->DT.format(x.contadoEn())).setHeader("Fecha/Hora");g.addColumn(RecuentoCajaDto::usuario).setHeader("Usuario");g.addColumn(x->money(x.esperado())).setHeader("Esperado").setTextAlign(ColumnTextAlign.END);g.addColumn(x->money(x.contado())).setHeader("Contado").setTextAlign(ColumnTextAlign.END);g.addColumn(x->money(x.diferencia())).setHeader("Diferencia").setTextAlign(ColumnTextAlign.END);g.addColumn(x->label(x.resultado())).setHeader("Resultado");g.addComponentColumn(x->new AppActionButton(ActionType.VIEW,ButtonSize.GRID_ACTION,"Ver recuento",e->{try{RecuentoCajaDto full=service.obtener(x.id());d.close();resultado(full);}catch(RuntimeException ex){UiErrorHandler.show(ex,"No fue posible cargar el recuento.");}})).setHeader("Acc.").setFlexGrow(0);g.setAllRowsVisible(true);HorizontalLayout pager=new HorizontalLayout();final int[] page={0};cargarHistorial(g,pager,page);d.add(g,pager);d.getFooter().add(new AppActionButton(ActionType.CLOSE,ButtonSize.MAIN,"Cerrar",e->d.close()));d.open();}
 private void cargarHistorial(Grid<RecuentoCajaDto> g,HorizontalLayout pager,int[] page){Page<RecuentoCajaDto> p=service.historial(sesionId,page[0]);g.setItems(p.getContent());pager.removeAll();Button prev=new Button(VaadinIcon.ANGLE_LEFT.create(),e->{page[0]--;cargarHistorial(g,pager,page);});prev.setEnabled(page[0]>0);Button next=new Button(VaadinIcon.ANGLE_RIGHT.create(),e->{page[0]++;cargarHistorial(g,pager,page);});next.setEnabled(page[0]+1<p.getTotalPages());pager.add(prev,new Span((page[0]+1)+" / "+Math.max(1,p.getTotalPages())),next);}
 private void cerrarSeguro(){boolean dirty=!observacion.getValue().isBlank()||campos.values().stream().anyMatch(x->x.getValue()!=null&&x.getValue()>0);if(!dirty){close();return;}ConfirmDialog c=new ConfirmDialog();c.setHeader("Descartar recuento");c.setText("Hay un recuento sin guardar. ¿Desea descartarlo?");c.setCancelable(true);c.setCancelText("Continuar contando");c.setConfirmText("Descartar");c.addConfirmListener(e->close());c.open();}
 private static Div info(String l,String v){Span value=new Span(v==null?"—":v);Div d=new Div(new Span(l),value);d.addClassName("cc-cash-count-info");return d;} private static Div infoTruncado(String l,String v){Div d=info(l,v);Span value=(Span)d.getComponentAt(1);value.addClassName("cc-cash-count-truncate");if(v!=null&&!v.isBlank())value.getElement().setAttribute("title",v);return d;} private static Div filaResultado(String l,String v){Div d=new Div(new Span(l),new Span(v));d.addClassName("cc-cash-count-result-row");return d;} private static String money(BigDecimal v){return PosNumberFormatter.money(v);} private static String label(ResultadoRecuentoCaja r){return switch(r){case BALANCED->"CUADRE CORRECTO";case OVERAGE->"SOBRANTE DE CAJA";case SHORTAGE->"FALTANTE DE CAJA";};} private static String amount(RecuentoCajaDto r,BigDecimal v){return r.monedaCodigo()+" "+money(v);} private static String signed(RecuentoCajaDto r,BigDecimal v){return r.monedaCodigo()+" "+(v.signum()>0?"+":"")+money(v);}
}
